import os,pwd,sys,json,hashlib,stat,signal,re,resource
from pathlib import Path
signal.alarm(45)
out={'status':'FAILED','scope':'Read-only D203 compile admission; no tool invocation, owner claim, source staging, MCU read or firmware operation','files':{}}
def need(condition,message):
 if not condition:raise ValueError(message)
def stamp(s):return (s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns)
def current_identity():
 u=os.uname();p=pwd.getpwuid(os.getuid())
 return dict(uid=os.getuid(),gid=os.getgid(),user=p.pw_name,home=p.pw_dir,sysname=u.sysname,release=u.release,machine=u.machine,python=list(sys.version_info[:3]),boot_id=Path('/proc/sys/kernel/random/boot_id').read_text().strip())
def credentials():
 status=Path('/proc/self/status').read_text()
 result={}
 for label in ('Uid','Gid','Groups'):
  rows=[line for line in status.splitlines() if line.startswith(label+':')]
  need(len(rows)==1,'Missing credential row')
  result[label.lower()]=[int(v) for v in rows[0].split(':',1)[1].split()]
 result['resuid']=list(os.getresuid());result['resgid']=list(os.getresgid())
 return result
try:
 out['identity']=current_identity();out['credentials']=credentials()
 need(out['identity']==PACKET['expected_identity'],'Board identity changed')
 need(out['credentials']['uid']==[1000]*4 and out['credentials']['gid']==[1000]*4 and out['credentials']['resuid']==[1000]*3 and out['credentials']['resgid']==[1000]*3,'UID/GID credentials changed')
 out['file_size_rlimit']=list(resource.getrlimit(resource.RLIMIT_FSIZE))
 need(tuple(out['file_size_rlimit'])==(resource.RLIM_INFINITY,resource.RLIM_INFINITY),'Inherited file-size limit')
 out['remote_owner_exists']=os.path.lexists(PACKET['remote_owner'])
 need(not out['remote_owner_exists'],'Remote owner already exists')
 out['ancestry']={}
 for name in ('/home/arduino',str(Path(PACKET['remote_owner']).parent)):
  p=Path(name);s=p.lstat();need(stat.S_ISDIR(s.st_mode) and p.resolve()==p,'Linked remote ancestry')
  out['ancestry'][name]=stamp(s)
 out['resources']={}
 for key,name in (('root_free_bytes','/'),('home_free_bytes','/home/arduino'),('tmp_free_bytes','/tmp')):
  s=os.statvfs(name);out['resources'][key]=s.f_bavail*s.f_frsize
 need(out['resources']['root_free_bytes']>=1073741824 and out['resources']['home_free_bytes']>=1073741824,'Less than 1GiB board free space')
 mem=Path('/proc/meminfo').read_text()
 for key in ('MemTotal','MemAvailable','SwapTotal','SwapFree'):
  rows=[line for line in mem.splitlines() if line.startswith(key+':')]
  need(len(rows)==1,'Missing memory observation')
  match=re.fullmatch(key+r':\s+([0-9]+) kB',rows[0]);need(match is not None,'Malformed memory observation')
  out['resources'][key+'_bytes']=int(match[1])*1024
 pids=sorted((p for p in Path('/proc').iterdir() if p.name.isdigit()),key=lambda p:int(p.name))
 need(len(pids)<=4096,'Process count bound')
 out['process_count']=len(pids);out['process_conflicts']=[];out['departed_pids']=[]
 for p in pids:
  try:
   with (p/'cmdline').open('rb') as f:raw=f.read(65537)
   with (p/'comm').open('rb') as f:comm=f.read(65537)
   need(len(raw)<=65536 and len(comm)<=65536,'Process metadata bound')
   need(not raw or raw.endswith(b'\0'),'Incomplete command line')
   args=raw.split(b'\0');name=Path(os.fsdecode(args[0])).name if args[0] else ''
   comm=comm.decode('utf-8').rstrip('\n')
  except FileNotFoundError:
   if os.path.lexists(p):raise
   out['departed_pids'].append(int(p.name));continue
  if any(n in ('arduino-cli','openocd','remoteocd','gdb','arm-zephyr-eabi-gdb') or re.fullmatch(r'(?:.*-)?(?:gcc|g\+\+|cc|c\+\+|cc1|cc1plus|collect2|as|ld|ld.bfd|lto-wrapper|lto1)',n) for n in (name,comm)):
   out['process_conflicts'].append({'pid':int(p.name),'argv0':os.fsdecode(args[0]),'comm':comm})
 need(not out['process_conflicts'],'Conflicting compile/native process')
 for name,expected in sorted(PACKET['pins'].items()):
  p=Path(name);before=p.lstat()
  need(stat.S_ISREG(before.st_mode) and 0<before.st_size<=134217728,'Nonordinary or oversized installed input: '+name)
  fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
  try:
   need(stamp(os.fstat(fd))==stamp(before),'Opened input drift: '+name)
   h=hashlib.sha256();total=0
   while True:
    chunk=os.read(fd,65536)
    if not chunk:break
    total+=len(chunk);need(total<=134217728,'Installed input read bound');h.update(chunk)
   need(stamp(os.fstat(fd))==stamp(before),'Read input drift: '+name)
  finally:os.close(fd)
  need(stamp(p.lstat())==stamp(before) and total==before.st_size,'Final input drift: '+name)
  out['files'][name]={'bytes':total,'sha256':h.hexdigest(),'identity':stamp(before),'expected_sha256':expected}
  need(h.hexdigest()==expected,'Installed input hash changed: '+name)
 out['closing_identity']=current_identity();out['closing_credentials']=credentials()
 need(out['closing_identity']==out['identity'] and out['closing_credentials']==out['credentials'],'Identity changed during observation')
 out['closing_remote_owner_exists']=os.path.lexists(PACKET['remote_owner'])
 need(not out['closing_remote_owner_exists'],'Remote owner appeared during observation')
 out['status']='PASS'
except Exception as error:
 out['error']={'type':type(error).__name__,'message':str(error)}
print(json.dumps(out,separators=(',',':')))
if out['status']!='PASS':raise SystemExit(1)
